using System;
using System.Text;
using UnityEngine;
using LWS.TruckSports;
using LWS.TruckBowling;
namespace LWS.TruckTerrierRacing {
public enum TerrierPhase {Countdown,Race,Replay,HeatResult,Complete}
public sealed class TerrierMatch:SportsEventSession {
 public override bool CompactViewportHud=>true;
 public override bool BroadcastHeaderVisible=>Phase==TerrierPhase.Replay||Phase==TerrierPhase.HeatResult||Phase==TerrierPhase.Complete;
 public override bool BroadcastStatusVisible=>BroadcastHeaderVisible||Phase==TerrierPhase.Race&&HeatWinner>=0;
 readonly int[] broadcastCards=new int[4];int cardsFrame=-1;
 void SelectBroadcastCards(){if(cardsFrame==Time.frameCount)return;cardsFrame=Time.frameCount;int count=0;for(int i=0;i<setup.count&&count<broadcastCards.Length;i++)if(setup.players[i].source!=BowlingSource.AI)broadcastCards[count++]=i;while(count<broadcastCards.Length&&count<setup.count){int best=-1;for(int i=0;i<setup.count;i++){bool used=false;for(int j=0;j<count;j++)if(broadcastCards[j]==i)used=true;if(!used&&(best<0||wins[i]>wins[best]))best=i;}if(best<0)break;broadcastCards[count++]=best;}}
 public override int ScoreCardCount=>Mathf.Min(4,setup.count);
 public override int ScoreCardSource(int card){SelectBroadcastCards();return broadcastCards[card];}
 public override string ScoreCardLabel(int card)=>setup.players[ScoreCardSource(card)].name;
 public override bool TryReadScoreCard(int card,out string value,out string detail){value=detail=null;if(card<0||card>=ScoreCardCount)return false;int slot=ScoreCardSource(card);var racer=racers[slot];value=wins[slot]+"/5";detail=racer.Finished?"FINISHED":!racer.Alive?"OUT":"HEAT "+Heat+" · RACING";return true;}
 public override bool TryReadViewportCard(int view,out int participant,out string score,out string detail){participant=-1;score=detail=null;if(view<0||view>=HumanViews||view>=viewSlots.Length)return false;participant=viewSlots[view];if(participant<0||participant>=racers.Length)return false;var racer=racers[participant];score=wins[participant]+" / 5";detail=Phase==TerrierPhase.Countdown?"HEAT "+Heat:racer.Finished?"FINISHED · LOCKED":!racer.Alive?"OUT · SPECTATING":"HEAT "+Heat+" · "+Mathf.Max(0,course.Length-course.TruckBounds(racer.truck.shape).max.z).ToString("F0")+"m";return true;}
 public override bool BroadcastParticipantActive(int slot)=>racers[slot].Alive&&!racers[slot].Finished;
 public override void DescribeBroadcast(SportsBroadcastAction action,SportsBroadcastFraming framing){int human=framing.Nearest(framing.RequestedFocus,true);action.primary=human>=0?human:framing.Nearest(framing.RequestedFocus);action.reason="LOCAL RACE ACTION / LEADING LIVE TRUCK";}
 public override bool SupportsRaceCountdown=>true;public override float RaceCountdownSeconds=>Phase==TerrierPhase.Countdown?Mathf.Max(0,3-phaseAge):-1;public override float RaceStartSeconds=>Phase==TerrierPhase.Race?HeatTime:-1;
 public TerrierVolcano volcano;public TerrierDessert dessert;public TerrierFinishDiagnostics finishDiagnostics;public TerrierWreckPool wrecks;public TerrierCrowd crowd;public TerrierSnow snow;public TerrierCountdown countdown;public float CountdownElapsed=>phaseAge;public TerrierRacer[] racers;public TerrierCourse course;public TerrierReplay replay;public SportsEventCamera broadcast;public SportsEventCamera[] cabViews;public ParticleSystem[] blasts;
 public TerrierPhase Phase{get;private set;}public float HeatTime{get;private set;}public int Heat{get;private set;}public int HeatWinner{get;private set;}=-1;public int MatchWinner{get;private set;}=-1;public int Seed{get;private set;}public int Locks{get;private set;}public int[] wins=new int[12];public int HumanViews{get;private set;}public int[] viewSlots=new int[4];
 readonly string[] wreckReason=new string[12];readonly float[] crashAt=new float[12];readonly Vector3[] crashPosition=new Vector3[12];readonly Bounds[] previous=new Bounds[12];readonly Vector3[][] previousCorners=new Vector3[12][],currentCorners=new Vector3[12][];readonly TerrierTunnelState[] tunnel=new TerrierTunnelState[12];readonly float[] finishTimes=new float[12],wreckTimes=new float[12],reactionAt=new float[12],jumpError=new float[12],laneError=new float[12],aiReverse=new float[12];readonly Vector2[] aiInput=new Vector2[12];readonly bool[] aiJump=new bool[12];readonly Quaternion[] headings=new Quaternion[4];readonly StringBuilder text=new StringBuilder(2000);public const float FinishWindow=8;public float FinishWindowRemaining=>float.IsPositiveInfinity(firstFinish)?0:Mathf.Max(0,FinishWindow-(HeatTime-firstFinish));float allOutAge;float firstFinish=float.PositiveInfinity;float phaseAge;int failures;uint wreckMask;bool replaySkip;string verdict="";
 public override string Title=>"TRUCK TERRIER RACING";public override int MinimumPlayers=>12;public override int MaximumPlayers=>12;public override int OptionCount=>2;public override string OptionLabel=>option==0?"IN TRUCK · HUMAN SPLIT SCREEN":"SHARED BROADCAST";public override bool MultiViewHUD=>option==0&&HumanViews>0&&(Phase==TerrierPhase.Race||Phase==TerrierPhase.Countdown);public override bool ReplayControls=>Phase==TerrierPhase.Replay;
 public override string SourcePolicy=>"Exactly twelve competitors · up to four humans · AI fills remaining slots. Whole-pad and shared-stick ownership is exclusive. Jump bindings are shown per source.";
 public override string Help=>"TRUCK TERRIER RACING\nTwelve physical trucks on a diagonal, gently descending triangular course. Stay wide through the racing section, then converge after the last wall toward the one finish box. Animated track runners can be bowled into ragdolls; they do not score. Snow accumulates and actual tires cut Weatherade tracks. Up to four local humans; AI fills the remaining stalls. First to FIVE heat wins takes the match. All stalls rotate fairly between heats. Each heat uses a reproducible passable hurdle layout and one shared random weather field.\n\nDRIVE with your movement source. Opposite throttle brakes, then reverses. ACTION jumps only while grounded with a short cooldown: keyboard key shown in setup, whole-pad SOUTH, shared-left LT, shared-right RT. Every racer has identical NWH traction, power, jump and weather. Time jumps a little before each hurdle. Limited airborne steering and gentle upright damping preserve forward momentum; actual hard collisions can still tumble you. Converge in the final funnel after the last wall.\n\nTHE TUNNEL: only a complete front-entry then rear-exit through the finish hole (25% wider opening) counts. Going over, around, or sideways into the barrier never wins. A high incoming wall-normal speed explodes the truck once; a gentle graze does not. The inner tunnel side faces are safe to brush; tiny physical contact tolerances cannot invalidate a genuine complete crossing. Only the official winner coasts off the exit into the colossal ice-cream bowl, with a real soft landing and squish. The opening closes behind the confirmed winner. Losing trucks fall toward the molten crater; lava contact produces impact effects and safely collects wreck pieces. Every ordinary wreck throws actual cab, chassis, doors and wheels as bounded physical pieces, also recorded in replay. Blasts can tumble neighbors. A locked legal finish is preserved against later debris. Missing a jump and remaining blocked for 1.1 seconds explodes the truck. After the first legal finish, the winner is locked and the heat continues for eight seconds to show the landing and remaining crashes before automatically ending. True simultaneous first finishes rerun with no point; all wrecked or 28 seconds without a legal finish also rerun. Repeated failures use the validated gentler fallback. No artificial winner.\n\nCAMERAS: In Truck gives each human a stable driver seat; AI uses no human viewport. Shared Broadcast shows the whole action. Eliminated drivers follow a live competitor. Every heat has a recorded nonphysical broadcast replay with launch and decisive finish/crash segments, angles, slow/fast speed, rewind and skip after one second. Replay cannot change the result. AI sessions advance automatically.\n\nPause/disconnect preserves the heat and replay. Reconnect or explicitly replace, release controls and confirm freshly. Configuration persists through rematches. Offline only.";
 public override string Header=>Title+" · HEAT "+Heat+" · FIRST TO FIVE · "+course.weather.Description;
 public override string Status=>Phase==TerrierPhase.Countdown?Mathf.Max(1,Mathf.CeilToInt(3-phaseAge)).ToString():Phase==TerrierPhase.Race&&!float.IsPositiveInfinity(firstFinish)?verdict+" · HEAT ENDS IN "+FinishWindowRemaining.ToString("F1")+"s":Phase==TerrierPhase.Race?"JUMP THE HURDLES · FINAL FUNNEL TO FINISH · "+HeatTime.ToString("F1")+"s":Phase==TerrierPhase.Replay?"RECORDED REPLAY · "+replay.PlaybackSpeed.ToString("F2")+"x · "+verdict:verdict;
 public override string Standings{get{text.Clear();for(int i=0;i<12;i++){text.Append("<color=#").Append(ColorUtility.ToHtmlStringRGB(setup.players[i].color)).Append(">").Append(setup.players[i].name).Append("</color> ").Append(wins[i]).Append(" / 5").Append(Phase==TerrierPhase.Race&&!racers[i].Alive?" · OUT":"").Append(i%4==3?'\n':' ');}return text.ToString();}}
 public override string Results=>setup.players[MatchWinner].name+" WINS THE MATCH\n\n"+Standings;
 public override string ViewText(int view){int slot=viewSlots[view];return "<color=#"+ColorUtility.ToHtmlStringRGB(setup.players[slot].color)+">"+setup.players[slot].name+"</color> · "+wins[slot]+" / 5  · HEAT "+Heat+"\n"+(Phase==TerrierPhase.Countdown?Status:racers[slot].Alive?racers[slot].Finished?"FINISHED · RESULT LOCKED":course.TruckBounds(racers[slot].truck.shape).max.z>=course.Length?"IN THE BOX · CLEAR THE REAR":"JUMP · "+Controls(slot)+"  |  "+Mathf.Max(0,course.Length-course.TruckBounds(racers[slot].truck.shape).max.z).ToString("F0")+"m TO TUNNEL":"WRECKED · LIVE SPECTATOR")+"\n"+course.weather.Description;}
 public override bool ValidateSources(out string reason){int humans=0;for(int i=0;i<setup.count;i++)if(setup.players[i].source!=BowlingSource.AI)humans++;if(humans>4){reason="Terrier Racing supports at most four local humans; remaining slots must be AI.";return false;}return base.ValidateSources(out reason);}
 protected override void BeginGame(){Array.Clear(wins,0,12);Heat=Locks=failures=0;MatchWinner=-1;Seed=UnityEngine.Random.Range(1,1000000);NewHeat();}
 void NewHeat(){Heat++;HeatTime=phaseAge=allOutAge=0;HeatWinner=-1;dessert?.ResetHeat();firstFinish=float.PositiveInfinity;Phase=TerrierPhase.Countdown;wreckMask=0;wrecks?.ResetHeat();replaySkip=false;verdict="";course.Generate(unchecked(Seed+Heat*997),Heat,failures>=2);if(!course.Valid()){course.Generate(1,Heat,true);if(!course.Valid())throw new InvalidOperationException("Terrier fallback is not passable");}dessert?.Align();volcano?.ResetHeat();Array.Clear(tunnel,0,12);var random=new System.Random(Seed+Heat*17);for(int i=0;i<12;i++){racers[i].Prepare(course.StartPosition(i,Heat));previous[i]=course.TruckBounds(racers[i].truck.shape);if(previousCorners[i]==null){previousCorners[i]=new Vector3[8];currentCorners[i]=new Vector3[8];}course.TruckCorners(racers[i].truck.shape,previousCorners[i]);finishTimes[i]=wreckTimes[i]=float.PositiveInfinity;reactionAt[i]=aiReverse[i]=0;aiInput[i]=Vector2.up;aiJump[i]=false;float error=setup.players[i].difficulty==BowlingDifficulty.Easy?2.8f:setup.players[i].difficulty==BowlingDifficulty.Normal?1.3f:.55f;jumpError[i]=((float)random.NextDouble()*2-1)*error;laneError[i]=((float)random.NextDouble()*2-1)*(setup.players[i].difficulty==BowlingDifficulty.Easy?.65f:setup.players[i].difficulty==BowlingDifficulty.Normal?.32f:.11f);}crowd.ResetHeat();snow.ResetHeat();replay.ResetRecord();Layout(false);Gate();Debug.Log("TERRIER_HEAT_BEGIN heat="+Heat+" seed="+course.Seed);}
 void Layout(bool shared){HumanViews=SportsCameraOptions.Select(setup,viewSlots);bool cab=!shared&&option==0&&HumanViews>0;broadcast.view.enabled=!cab;for(int i=0;i<4;i++){cabViews[i].view.enabled=cab&&i<HumanViews;cabViews[i].view.rect=LWS.TruckCornhole.CornholeMatch.ViewRect(Mathf.Max(1,HumanViews),i);headings[i]=course.Heading;}cameras=cab?new Camera[HumanViews]:new[]{broadcast.view};course.weather.vendor.AllowCameras.Clear();if(cab){for(int i=0;i<HumanViews;i++){cameras[i]=cabViews[i].view;course.weather.vendor.AllowCameras.Add(cameras[i]);}}else course.weather.vendor.AllowCameras.Add(broadcast.view);}
 public void JumpEvent(int slot){replay.RecordJump(slot,HeatTime);feedback.Play(4,0,true);}
 public void QueueWreck(int slot,float time,string reason="PHYSICAL_FAILURE"){if(Phase!=TerrierPhase.Race||!racers[slot].Alive)return;if(racers[slot].Finished){finishDiagnostics?.Event(slot,"QUEUED_AFTER_FINISH_IGNORED "+reason,time,course.TruckBounds(racers[slot].truck.shape));return;}if((wreckMask&(1u<<slot))!=0&&wreckTimes[slot]<=time)return;wreckMask|=1u<<slot;wreckTimes[slot]=time;wreckReason[slot]=reason;}
 public void CreamLanding(int slot){if(!racers[slot].Alive||!racers[slot].Finished||HeatWinner!=slot)return;racers[slot].LandInCream();crashAt[slot]=HeatTime;crashPosition[slot]=racers[slot].truck.body.position;finishDiagnostics?.Event(slot,"WINNER_PHYSICAL_ICE_CREAM_LANDING",Time.fixedTime,course.TruckBounds(racers[slot].truck.shape));} void Wreck(int slot){if(!racers[slot].Alive||racers[slot].Finished){if(racers[slot].Finished)finishDiagnostics?.Event(slot,"PENDING_WRECK_IGNORED_FINISH_LOCKED",wreckTimes[slot],course.TruckBounds(racers[slot].truck.shape));return;}finishDiagnostics?.Event(slot,"WRECK "+wreckReason[slot],wreckTimes[slot],course.TruckBounds(racers[slot].truck.shape));var p=racers[slot].truck.body.position;crashAt[slot]=HeatTime;crashPosition[slot]=p;replay.Crash(slot,HeatTime,p);wrecks?.Emit(slot);racers[slot].Wreck();var fx=blasts[slot%blasts.Length];fx.transform.position=p;fx.Play();Pulse(slot,.5f,.2f);feedback.Play(2,0,true);for(int i=0;i<12;i++)if(racers[i].Alive&&!racers[i].Finished){var d=racers[i].truck.body.position-p;float distance=d.magnitude;if(distance>7)continue;d.y=Mathf.Max(2,d.y+2);racers[i].truck.body.AddForce(d.normalized*Mathf.Lerp(7,1,distance/7),ForceMode.VelocityChange);racers[i].truck.body.AddTorque(new Vector3(1,0,2),ForceMode.VelocityChange);}Debug.Log("TERRIER_WRECK slot="+slot+" time="+HeatTime);}
 void AI(int i){var r=racers[i];var p=course.Local(r.truck.body.position);var level=setup.players[i].difficulty;if(aiReverse[i]>0){aiReverse[i]-=Time.fixedDeltaTime;aiInput[i]=new Vector2(i%2==0?.7f:-.7f,-.75f);aiJump[i]=false;return;}if(r.Blocked>1.3f){aiReverse[i]=.7f;return;}if(HeatTime<reactionAt[i])return;float look=Mathf.Lerp(6,11,Mathf.InverseLerp(0,22,r.Incoming.magnitude));var aim=course.World(new Vector3(course.Lane(p.z+look,i,Heat)+laneError[i],p.y,p.z+look));float angle=Vector3.SignedAngle(Vector3.ProjectOnPlane(r.truck.transform.forward,Vector3.up),Vector3.ProjectOnPlane(aim-r.truck.body.position,Vector3.up),Vector3.up);bool backwards=Mathf.Abs(angle)>120;if(backwards)angle=Mathf.DeltaAngle(0,angle-180);aiInput[i]=new Vector2(Mathf.Clamp(angle/30,-1,1)*(backwards?-1:1),(Mathf.Abs(angle)>60?.55f:1)*(backwards?-1:1));float gap=course.NextHurdle(p.z)-p.z;float threshold=Mathf.Clamp(Mathf.Abs(Vector3.Dot(r.Incoming,course.Forward))*.32f+2+jumpError[i],4,10);aiJump[i]=gap>0&&gap<threshold;reactionAt[i]=HeatTime+(level==BowlingDifficulty.Easy?.24f:level==BowlingDifficulty.Normal?.13f:.07f);}
 protected override void Simulate(float dt){phaseAge+=dt;snow.Step(dt);if(Phase==TerrierPhase.Countdown){course.weather.Tick(0);if(phaseAge>=3){course.OpenGates();foreach(var r in racers)r.Release();Phase=TerrierPhase.Race;HeatTime=phaseAge=0;for(int i=0;i<12;i++){previous[i]=course.TruckBounds(racers[i].truck.shape);course.TruckCorners(racers[i].truck.shape,previousCorners[i]);}replay.Record(0,true);}return;}if(Phase==TerrierPhase.Replay){if(replay.Step(dt)||replaySkip&&replay.Age>=1){replay.End();Phase=TerrierPhase.HeatResult;phaseAge=0;}return;}if(Phase==TerrierPhase.HeatResult){if(phaseAge<1.3f)return;if(MatchWinner>=0){Phase=TerrierPhase.Complete;EndMatch();}else NewHeat();return;}if(Phase!=TerrierPhase.Race)return;
 HeatTime+=dt;dessert?.Step(dt);course.weather.Tick(HeatTime);crowd.Step(dt);int legal=0;for(int i=0;i<12;i++)if(float.IsPositiveInfinity(firstFinish)&&racers[i].Alive&&!racers[i].Finished){var bounds=course.TruckBounds(racers[i].truck.shape);course.TruckCorners(racers[i].truck.shape,currentCorners[i]);if(TerrierRules.Crossing(ref tunnel[i],previousCorners[i],currentCorners[i],course.Length,out float fraction)){float timestamp=Time.fixedTime-dt+fraction*dt;if(timestamp<=wreckTimes[i]+.0001f){finishTimes[i]=HeatTime-dt+fraction*dt;finishDiagnostics?.Event(i,"FINISH_CANDIDATE",timestamp,bounds);legal++;}}previous[i]=bounds;Array.Copy(currentCorners[i],previousCorners[i],8);}
 if(legal>0&&float.IsPositiveInfinity(firstFinish)){HeatWinner=TerrierRules.Winner(finishTimes);if(HeatWinner>=0){racers[HeatWinner].Finish();dessert?.AuthorizeWinner(HeatWinner);finishDiagnostics?.Event(HeatWinner,"OFFICIAL_FINISH_LOCKED",Time.fixedTime-dt+(finishTimes[HeatWinner]-(HeatTime-dt)),course.TruckBounds(racers[HeatWinner].truck.shape));}firstFinish=HeatTime;verdict=HeatWinner<0?"PHOTO FINISH TIE · HEAT REPLAYED":setup.players[HeatWinner].name+" THROUGH FIRST";feedback.Play(5,0,true);Debug.Log("TERRIER_FIRST_FINISH heat="+Heat+" winner="+HeatWinner+" time="+firstFinish);}
 for(int i=0;i<12;i++)if((wreckMask&(1u<<i))!=0)Wreck(i);wreckMask=0;bool any=false;for(int i=0;i<12;i++)if(racers[i].Alive){any=true;bool ai=setup.players[i].source==BowlingSource.AI;if(ai)AI(i);racers[i].Step(ai?aiInput[i]:commands[i],ai?aiJump[i]:actions[i],dt);aiJump[i]=false;}replay.Record(HeatTime);if(!float.IsPositiveInfinity(firstFinish)){if(HeatTime-firstFinish>=FinishWindow)FinishHeat(HeatWinner,verdict);}else {allOutAge=!any?allOutAge+dt:0;if(allOutAge>=1.6f||HeatTime>=28)FinishHeat(-1,!any?"ALL WRECKED · NO POINT · RERUN":"NO LEGAL FINISH · NO POINT · RERUN");}
 }
 void FinishHeat(int winner,string message){if(Phase!=TerrierPhase.Race)return;HeatWinner=winner;verdict=message;Locks++;if(winner>=0){wins[winner]++;failures=0;if(wins[winner]>=5)MatchWinner=winner;}else failures++;replay.DecisiveTime=winner>=0?finishTimes[winner]:HeatTime;replay.Record(HeatTime,true);Phase=TerrierPhase.Replay;phaseAge=0;Layout(true);replay.Begin();Gate();feedback.Play(winner>=0?5:2,0,true);Debug.Log("TERRIER_HEAT_LOCK heat="+Heat+" winner="+winner+" time="+HeatTime+" wins="+string.Join(",",wins));}
 public override void ExtraAction(string key){if(Phase!=TerrierPhase.Replay)return;if(key=="replayangle"){replay.Angle=(replay.Angle+1)%4;replay.AutoAngles=false;}else if(key=="replayspeed")replay.PlaybackSpeed=replay.PlaybackSpeed<.5f?1:replay.PlaybackSpeed<1.5f?2:replay.PlaybackSpeed<3?4:.25f;else if(key=="replayrewind")replay.Seek(Mathf.Max(0,replay.TimeCursor-3));else if(key=="replayskip"&&replay.Age>=1)replaySkip=true;ConsumeActions();}
 int Spectator(int preferred){if(preferred>=0&&racers[preferred].Alive)return preferred;int choice=0;float best=float.NegativeInfinity;for(int i=0;i<12;i++)if(racers[i].Alive&&course.Local(racers[i].truck.body.position).z>best){best=course.Local(racers[i].truck.body.position).z;choice=i;}return choice;}
 protected override void Present(float dt){if(racers==null||racers.Length!=12)return;int leader=Spectator(-1);var focus=Phase==TerrierPhase.Replay?replay.Focus:racers[leader].truck.body.position;Vector3 offset=Phase==TerrierPhase.Replay?(replay.Angle==0?new Vector3(12,9,-16):replay.Angle==1?new Vector3(-12,6,12):replay.Angle==2?new Vector3(0,30,-3):new Vector3(4,2,-9)):new Vector3(0,26,-25);broadcast.Pose(focus+course.Heading*Vector3.forward*7,course.Heading*offset,Phase==TerrierPhase.Replay?62:76,Phase==TerrierPhase.Replay&&replay.Age<.06f||Phase==TerrierPhase.Countdown&&phaseAge<.06f);for(int v=0;v<HumanViews&&v<4;v++){if(!cabViews[v].view.enabled)continue;int owner=viewSlots[v],slot=Spectator(owner);var r=racers[slot];cabViews[v].cabSteering?.Bind(r.truck);if(!racers[owner].Alive){cabViews[v].view.cullingMask=~(15<<25);cabViews[v].Pose(HeatTime-crashAt[owner]<1.6f?crashPosition[owner]:r.truck.body.position,course.Heading*new Vector3(6,4,-9),70);continue;}var forward=Vector3.ProjectOnPlane(r.truck.transform.forward,Vector3.up);if(forward.sqrMagnitude>.1f&&Vector3.Dot(r.truck.transform.up,Vector3.up)>.2f)headings[v]=Quaternion.Slerp(headings[v],Quaternion.LookRotation(forward),1-Mathf.Exp(-dt*7));var camera=cabViews[v].view;camera.cullingMask=(~(1<<(10+slot)))&~(15<<25)|(1<<(25+v));camera.fieldOfView=80;camera.transform.SetPositionAndRotation(r.truck.body.position+Vector3.up*1.05f+headings[v]*new Vector3(-.25f,0,1.08f),headings[v]);}}
 protected override void SetPaused(bool paused){course?.weather?.Pause(paused);dessert?.Pause(paused);}
 protected override void StopGame(){dessert?.Stop();wrecks?.Clear();crowd?.Stop();snow?.StopTraces();if(replay!=null)replay.End();if(racers!=null)foreach(var r in racers){r.truck.Power(false);if(!r.truck.body.isKinematic)r.truck.body.linearVelocity=r.truck.body.angularVelocity=Vector3.zero;r.truck.body.isKinematic=true;}}
 protected override void StopSounds(){dessert?.StopAudio();if(racers!=null)foreach(var r in racers)r.truck.StopSound();}
}
}
